<?php
header("Content-Type: application/json");
$b64 = "";
$new_content = base64_decode($b64);
$target = __DIR__ . "/dps_cache_clear.php";

// Escrever o ficheiro
$ok = file_put_contents($target, $new_content);

// Invalidar opcache
if (function_exists("opcache_invalidate")) opcache_invalidate($target, true);
if (function_exists("opcache_reset")) opcache_reset();

// Verificar o que está no disco
$on_disk = file_get_contents($target);

echo json_encode([
    "write_ok" => $ok !== false,
    "bytes_written" => $ok,
    "bytes_expected" => strlen($new_content),
    "on_disk_size" => strlen($on_disk),
    "on_disk_has_check_sofia" => strpos($on_disk, "check_sofia") !== false,
    "on_disk_mtime" => date("Y-m-d H:i:s", filemtime($target)),
    "match" => $on_disk === $new_content,
]);
